df = df.sort_values('Date').reset_index(drop=True)

# 2. Calculate KPIs
earliest_close = df['Close'].iloc[0]
latest_close = df['Close'].iloc[-1]
cumulative_return = (latest_close / earliest_close) - 1

days = (df['Date'].iloc[-1] - df['Date'].iloc[0]).days
years = days / 365.25
cagr = (latest_close / earliest_close) ** (1 / years) - 1

df['Daily_Return'] = df['Close'].pct_change()
annualized_volatility = df['Daily_Return'].std() * np.sqrt(252)

df['Cumulative_Max'] = df['Close'].cummax()
df['Drawdown'] = (df['Close'] - df['Cumulative_Max']) / df['Cumulative_Max']
max_drawdown = df['Drawdown'].min()

total_dividends = df['Dividends'].sum()

# Helper function to create base64 charts
def get_base64_plot(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=150)
    buf.seek(0)
    img_str = base64.b64encode(buf.read()).decode('utf-8')
    plt.close(fig)
    return f"data:image/png;base64,{img_str}"

plt.style.use('bmh')

# Chart 1: Long-Term Price Trend (Log Scale)
fig, ax = plt.subplots(figsize=(10, 5))
ax.plot(df['Date'], df['Close'], color='#1f77b4', linewidth=1.5)
ax.set_yscale('log')
ax.set_title('AXP Long-Term Price Trend (Log Scale)', fontsize=14)
ax.set_ylabel('Closing Price (USD)', fontsize=12)
ax.grid(True, which="both", ls="--", alpha=0.5)
chart_price_trend = get_base64_plot(fig)

# Chart 2: Drawdowns
fig, ax = plt.subplots(figsize=(10, 4))
ax.fill_between(df['Date'], df['Drawdown'], 0, color='#d62728', alpha=0.7)
ax.set_title('Historical Drawdowns', fontsize=14)
ax.set_ylabel('Drawdown (%)', fontsize=12)
ax.yaxis.set_major_formatter(plt.FuncFormatter(lambda y, _: '{:.0%}'.format(y)))
chart_drawdowns = get_base64_plot(fig)

# Chart 3: Volume Over Time
fig, ax = plt.subplots(figsize=(10, 4))
ax.plot(df['Date'], df['Volume'].rolling(window=60).mean(), color='#2ca02c', linewidth=1.5)
ax.set_title('Trading Volume (60-Day Moving Average)', fontsize=14)
ax.set_ylabel('Volume', fontsize=12)
chart_volume = get_base64_plot(fig)

# Chart 4: Dividends
dividends_df = df[df['Dividends'] > 0]
fig, ax = plt.subplots(figsize=(10, 4))
ax.vlines(dividends_df['Date'], 0, dividends_df['Dividends'], color='#9467bd', linewidth=2)
ax.set_title('Dividend Payments Over Time', fontsize=14)
ax.set_ylabel('Dividend Amount (USD)', fontsize=12)
chart_dividends = get_base64_plot(fig)

